class ClassRegistrationSystem:

    def __init__(self):
        self._students = []
        self._students_registration_classes = {}

    def students(self):
        return self._students.copy()

    def students_registration_classes(self):
        return {student: classes.copy() for student, classes in self._students_registration_classes.items()}

    def register_student(self, student):
        if self._is_student_registered(student):
            return 0
        self._add_student(student)
        return 1

    def _is_student_registered(self, student):
        return student in self._students

    def _add_student(self, student):
        self._students.append(student)

    def register_class(self, student_name, class_name):
        if self._student_has_registrations(student_name):
            self._append_class_to_student(student_name, class_name)
        else:
            self._initialize_student_registrations(student_name, class_name)
        return self._get_registration_classes(student_name)

    def _student_has_registrations(self, student_name):
        return student_name in self._students_registration_classes

    def _append_class_to_student(self, student_name, class_name):
        self._students_registration_classes[student_name].append(class_name)

    def _initialize_student_registrations(self, student_name, class_name):
        self._students_registration_classes[student_name] = [class_name]

    def _get_registration_classes(self, student_name):
        return self._students_registration_classes[student_name]

    def get_students_by_major(self, major):
        return [student["name"] for student in self._students if student["major"] == major]

    def get_all_major(self):
        return list({student["major"] for student in self._students})

    def get_most_popular_class_in_major(self, major):
        class_list = self._get_class_list_for_major(major)
        return self._find_most_popular_class(class_list)

    def _get_class_list_for_major(self, major):
        return [
            class_name
            for student in self._students
            if student["major"] == major
            for class_name in self._students_registration_classes.get(student["name"], [])
        ]

    def _find_most_popular_class(self, class_list):
        if not class_list:
            return None
        return max(set(class_list), key=class_list.count)
